import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';


const routes: Routes = [
  {
    path: '', redirectTo: 'dashboard', pathMatch: 'full'
  },
  {
    path: 'dashboard', loadComponent: () => import('../../components/admindashboard/admindashboard.component').then(m => m.AdmindashboardComponent)
  },
  {
    path: 'tickets/:id', loadComponent: () => import('../../../shared/components/tickets/tickets.component').then(m => m.TicketsComponent)
  },
  {
    path: 'archivecases', loadComponent: () => import('../../components/archivecase/archivecase.component').then(m => m.ArchivecaseComponent)
  },
  { path: 'batchlog/:id', loadComponent: () => import('../../components/bundlemanagement/batch/batchlog/batchlog.component').then(m => m.BatchlogComponent) },
];
@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class AdmindashboardRoutingModule { }
